<script setup>
import { ref, computed, onUnmounted } from 'vue'
import { LayoutDashboard, Files, SlidersHorizontal, Bookmark, Sparkles, UploadCloud, ArrowUpRight, Search, ChevronRight, Car, X, Check, LogOut, RefreshCw, FileText, AlertTriangle, Building2 } from 'lucide-vue-next'
const username=ref('admin'), password=ref(''), auth=ref(''), view=ref('dashboard'), error=ref(''), busy=ref(false)
const catalogs=ref([]), selected=ref(null), lots=ref([]), analysis=ref(null), history=ref([]), config=ref({}), file=ref(null), house=ref(''), query=ref(''), filter=ref('ALL')
const detail=ref(null), edit=ref(null), uploadInput=ref(null), inputRate=ref(0), outputRate=ref(0)
const criteria=ref({capital:65000000,maxPerUnit:65000000,maxBid:60000000,targetProfit:5000000,auctionFee:2500000,auctionFeePercent:0,repairBuffer:3000000,taxBuffer:2000000,otherCosts:1000000,riskBuffer:2000000,minYear:2012,maxKilometer:150000,transmission:'ALL',buyer:'DEALER',strategy:'FAST',requireStnk:true,requireBpkb:true,instructions:''})
const moneyFields=[['capital','Modal tersedia'],['maxPerUnit','Modal maksimal / unit'],['maxBid','Maksimum harga bid (tanpa biaya)'],['targetProfit','Target laba bersih'],['repairBuffer','Buffer servis'],['taxBuffer','Buffer pajak'],['otherCosts','Transport & biaya lain'],['riskBuffer','Cadangan risiko']]
const nav=[['dashboard','Overview',LayoutDashboard],['catalogs','Katalog lelang',Files],['analysis','Analisis unit',SlidersHorizontal],['watchlist','Bid board',Bookmark],['ai','AI & penggunaan',Sparkles],['houses','Balai lelang',Building2],['won','Unit dimenangkan',Car]]
const bidPreview=ref(null)
async function previewBid(){await perform(async()=>{bidPreview.value=await api(`/catalogs/${selected.value.id}/cost-preview`,{method:'POST',body:JSON.stringify({bid:criteria.value.maxBid})})})}
const houses=ref([]), houseForm=ref(null), catalogHouse=ref('')
const activeHouses=computed(()=>houses.value.filter(h=>h.active))
async function refreshHouses(){houses.value=await api('/auction-houses');if(!house.value||!activeHouses.value.some(h=>h.id===house.value))house.value=activeHouses.value[0]?.id||''}
function editHouse(h){houseForm.value=h?{id:h.id,name:h.name,adminFee:h.admin_fee,taxPercent:Number(h.tax_percent),active:h.active}:{name:'',adminFee:0,taxPercent:0,active:true}}
async function saveHouse(){await perform(async()=>{const h=houseForm.value;await api(`/auction-houses${h.id?'/'+h.id:''}`,{method:h.id?'PUT':'POST',body:JSON.stringify(h)});await refreshHouses();houseForm.value=null})}
async function deleteHouse(h){if(!window.confirm(`Hapus balai ${h.name}? Balai yang sudah dipakai katalog harus dinonaktifkan.`))return;await perform(async()=>{await api(`/auction-houses/${h.id}`,{method:'DELETE'});await refreshHouses()})}
async function applyCatalogHouse(){await perform(async()=>{await api(`/catalogs/${selected.value.id}/house`,{method:'PUT',body:JSON.stringify({houseId:catalogHouse.value})});selected.value=await api(`/catalogs/${selected.value.id}`);bidPreview.value=null;lots.value=await api(`/catalogs/${selected.value.id}/lots`);await refreshCatalogs()})}
const wonUnits=ref([]), funds=ref({startingFunds:0,realizedProfit:0,funds:0,unsoldCapital:0}), startingFunds=ref(0), wonForm=ref(null), wonDetail=ref(null), expenseForm=ref(null)
const today=()=>new Date().toLocaleDateString('en-CA')
const wonFields=[['vehicle','Nama unit','text',true],['year','Tahun','number',false],['lotNumber','Nomor lot','text',false],['kilometer','Kilometer','number',false],['plate','Plat nomor','text',false],['basePrice','Harga dasar (Rp)','number',false],['idealBid','Harga menang ideal (Rp)','number',false],['winningBid','Harga menang aktual (Rp)','number',true],['wonDate','Tanggal menang','date',true],['medianPrice','Median harga pasar (Rp)','number',false],['targetPrice','Harga iklan / target jual (Rp)','number',false],['dealPrice','Harga deal jual (Rp)','number',false],['soldDate','Tanggal terjual','date',false],['link','Link referensi','url',false]]
async function refreshWon(){[wonUnits.value,funds.value]=await Promise.all([api('/won-units'),api('/won-units/funds')]);startingFunds.value=funds.value.startingFunds}
async function saveFunds(){await perform(async()=>{await api('/won-units/funds',{method:'PUT',body:JSON.stringify({startingFunds:startingFunds.value})});await refreshWon()})}
function newWon(lot=null){const d=lot?.data||{};wonForm.value={houseId:lot?selected.value.auction_house_id:(activeHouses.value[0]?.id||''),sourceLotId:lot?.id||null,data:{vehicle:d.vehicle||'',year:d.year??'',lotNumber:lot?.lot_number||'',kilometer:d.kilometer??'',plate:'',basePrice:d.basePrice??'',idealBid:results.value.find(r=>r.lotId===lot?.id)?.maxBid||'',winningBid:'',wonDate:today(),medianPrice:'',targetPrice:'',dealPrice:'',soldDate:'',notes:'',link:''}};error.value=''}
function editWon(u){wonForm.value={id:u.id,houseId:u.auction_house_id,sourceLotId:u.source_lot_id,data:JSON.parse(JSON.stringify(u.data))};error.value=''}
async function saveWon(){await perform(async()=>{const f=wonForm.value;const data={...f.data};for(const k of ['year','kilometer','basePrice','idealBid','medianPrice','targetPrice','dealPrice'])data[k]=data[k]===''||data[k]==null?null:Number(data[k]);data.winningBid=Number(data.winningBid);data.soldDate||=null;await api(`/won-units${f.id?'/'+f.id:''}`,{method:f.id?'PUT':'POST',body:JSON.stringify({houseId:f.houseId,sourceLotId:f.sourceLotId,data})});wonForm.value=null;view.value='won';await refreshWon();if(wonDetail.value)await loadWon(wonDetail.value.id)})}
async function loadWon(id){wonDetail.value=await api('/won-units/'+id);expenseForm.value=null}
async function deleteWon(u){if(!window.confirm(`Hapus ${u.data.vehicle} beserta seluruh pengeluarannya?`))return;await perform(async()=>{await api('/won-units/'+u.id,{method:'DELETE'});wonDetail.value=null;await refreshWon()})}
function editExpense(e=null){expenseForm.value=e?{id:e.id,date:e.expense_date,category:e.category,description:e.description,amount:e.amount}:{date:today(),category:'Servis',description:'',amount:''}}
async function saveExpense(){await perform(async()=>{const e=expenseForm.value,id=wonDetail.value.id;await api(`/won-units/${id}/expenses${e.id?'/'+e.id:''}`,{method:e.id?'PUT':'POST',body:JSON.stringify({...e,amount:Number(e.amount)})});await loadWon(id);await refreshWon()})}
async function deleteExpense(e){if(!window.confirm('Hapus pengeluaran ini?'))return;await perform(async()=>{const id=wonDetail.value.id;await api(`/won-units/${id}/expenses/${e.id}`,{method:'DELETE'});await loadWon(id);await refreshWon()})}
let timer, polling=false
const idr=v=>v==null?'—':new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v)
const short=v=>v==null?'—':`${new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(v/1000000)} jt`
const results=computed(()=>analysis.value?.results||[])
const visible=computed(()=>results.value.filter(r=>(view.value!=='watchlist'||r.watchlisted)&&(filter.value==='ALL'||r.recommendation===filter.value)&&`${r.vehicle} ${r.lotNumber}`.toLowerCase().includes(query.value.toLowerCase())))
const bids=computed(()=>results.value.filter(r=>r.recommendation==='BID').length)
const top=computed(()=>results.value.find(r=>r.recommendation==='BID'))
const usageCost=computed(()=>((analysis.value?.usage?.inputTokens||0)*inputRate.value+(analysis.value?.usage?.outputTokens||0)*outputRate.value)/1000000)
async function api(path,options={}){
 const headers={'Authorization':`Basic ${auth.value}`,'X-PhiveGarage':'web',...options.headers}
 if(options.body && !(options.body instanceof FormData))headers['Content-Type']='application/json'
 const response=await fetch(`/api${path}`,{...options,headers})
 if(response.status===401){auth.value='';throw Error('Username atau password tidak cocok.')}
 if(!response.ok){let data;try{data=await response.json()}catch{}throw Error(data?.message||data?.detail||`Request gagal (${response.status})`)}
 return response.json()
}
async function perform(action){error.value='';busy.value=true;try{await action()}catch(e){error.value=e.message}finally{busy.value=false}}
async function login(){await perform(async()=>{auth.value=btoa(unescape(encodeURIComponent(`${username.value}:${password.value}`)));try{config.value=await api('/config');await refreshCatalogs();await refreshHouses();password.value='';timer=setInterval(poll,2500)}catch(e){auth.value='';throw e}})}
function logout(){auth.value='';clearInterval(timer);catalogs.value=[];selected.value=null;lots.value=[];analysis.value=null;history.value=[]}
async function refreshCatalogs(){catalogs.value=await api('/catalogs')}
async function loadCatalog(c){await perform(async()=>{selected.value=await api(`/catalogs/${c.id}`);lots.value=await api(`/catalogs/${c.id}/lots`);history.value=await api(`/catalogs/${c.id}/analyses`);analysis.value=history.value[0]||null;if(analysis.value?.parameters)criteria.value={...criteria.value,...analysis.value.parameters,maxBid:analysis.value.parameters.maxBid||60000000,requireStnk:true};bidPreview.value=null;catalogHouse.value=selected.value.auction_house_id||'';view.value='analysis'})}
async function poll(){
 if(!auth.value||polling)return;polling=true
 try{
  if(catalogs.value.some(c=>['QUEUED','EXTRACTING'].includes(c.status)))await refreshCatalogs()
  if(selected.value&&['QUEUED','EXTRACTING'].includes(selected.value.status)){
   selected.value=await api(`/catalogs/${selected.value.id}`)
   if(selected.value.status==='READY')lots.value=await api(`/catalogs/${selected.value.id}/lots`)
  }
  if(analysis.value&&['QUEUED','PROCESSING'].includes(analysis.value.status)){
   analysis.value=await api(`/analyses/${analysis.value.id}`)
   if(['READY','FAILED'].includes(analysis.value.status))history.value=await api(`/catalogs/${selected.value.id}/analyses`)
  }
 }catch(e){error.value=e.message}finally{polling=false}
}
onUnmounted(()=>clearInterval(timer))
async function upload(){await perform(async()=>{
 if(!file.value)throw Error('Pilih PDF katalog terlebih dahulu.')
 const body=new FormData();body.append('file',file.value);body.append('houseId',house.value)
 const c=await api('/catalogs',{method:'POST',body});await refreshCatalogs();await loadCatalog(c);file.value=null;if(uploadInput.value)uploadInput.value.value=''
})}
async function retryExtraction(){await perform(async()=>{await api(`/catalogs/${selected.value.id}/retry`,{method:'POST'});selected.value=await api(`/catalogs/${selected.value.id}`);await refreshCatalogs()})}
async function run(){await perform(async()=>{const a=await api(`/catalogs/${selected.value.id}/analyses`,{method:'POST',body:JSON.stringify(criteria.value)});analysis.value=await api(`/analyses/${a.id}`);history.value=await api(`/catalogs/${selected.value.id}/analyses`)})}
async function setWatch(r){await perform(async()=>{await api(`/analyses/${analysis.value.id}/watchlist/${r.lotId}`,{method:'PATCH',body:JSON.stringify({watchlisted:!r.watchlisted})});r.watchlisted=!r.watchlisted})}
function openEdit(lot){edit.value=JSON.parse(JSON.stringify(lot));edit.value.data.comparables||=[]}
async function saveLot(){await perform(async()=>{for(const k of ['year','kilometer','basePrice','repairCost','taxCost','otherCost','taxExpiry'])if(edit.value.data[k]==='')edit.value.data[k]=null;await api(`/lots/${edit.value.id}`,{method:'PUT',body:JSON.stringify({data:edit.value.data,verified:edit.value.verified})});lots.value=await api(`/catalogs/${selected.value.id}/lots`);edit.value=null})}
async function openPdf(){await perform(async()=>{const res=await fetch(`/api/catalogs/${selected.value.id}/pdf`,{headers:{Authorization:`Basic ${auth.value}`,'X-PhiveGarage':'web'}});if(!res.ok)throw Error('PDF gagal dibuka');const url=URL.createObjectURL(await res.blob());window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)})}
function download(){const body=JSON.stringify({catalog:selected.value,analysis:analysis.value},null,2);const url=URL.createObjectURL(new Blob([body],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='phivegarage-analysis.json';a.click();URL.revokeObjectURL(url)}
const statusLabel=s=>({BID:'Layak bid',REVIEW:'Perlu diperiksa',SKIP:'Lewati',QUEUED:'Dalam antrean',EXTRACTING:'Membaca PDF',PROCESSING:'Menganalisis',READY:'Siap',FAILED:'Gagal'})[s]||s
</script>

<template>
 <div v-if="!auth" class="login-shell"><div class="login-art"><div class="brand"><span class="brand-mark">P</span> phivegarage<span class="brand-dot">.</span></div><div><span class="eyebrow">AUCTION INTELLIGENCE</span><h1>Bid dengan data.<br>Putar modal<br><em>lebih terarah.</em></h1><p>Dari katalog lelang ke shortlist pilihanmu.<br>Satu tempat untuk menilai risiko dan menghitung batas bid.</p></div><small>BUILT FOR YOUR NEXT GOOD DEAL</small></div><form class="login-card" @submit.prevent="login"><span class="eyebrow">WELCOME TO YOUR GARAGE</span><h2>Masuk ke workspace</h2><p>Gunakan akun yang kamu konfigurasi di server.</p><label>Username<input v-model="username" autocomplete="username" required></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required></label><div v-if="error" class="error">{{ error }}</div><button class="primary" :disabled="busy">{{ busy?'Menghubungkan…':'Masuk' }} <ArrowUpRight :size="18"/></button></form></div>
 <div v-else class="app-shell">
 <aside class="sidebar"><div class="brand"><span class="brand-mark">P</span> phivegarage<span class="brand-dot">.</span></div><span class="workspace-label">PERSONAL WORKSPACE</span><nav><button v-for="[id,label,icon] in nav" :key="id" :class="{active:view===id}" @click="view=id; if(id==='won') perform(refreshWon)"><component :is="icon" :size="19"/>{{label}}<ChevronRight v-if="view===id" :size="15"/></button></nav><div class="sidebar-note"><span class="live-dot"></span> Decision support<p>Periksa unit langsung sebelum bidding. Hasil analisis membantu menilai, bukan menjamin kondisi.</p></div><button class="account" @click="logout"><span class="avatar">{{ username.slice(0,1).toUpperCase() }}</span><span>{{username}}<small>Private garage</small></span><LogOut :size="17"/></button></aside>
 <main><header class="topbar"><span>Workspace <ChevronRight :size="14"/> <b>{{nav.find(n=>n[0]===view)?.[1]}}</b></span><span class="topbar-status"><span class="live-dot"></span> {{config.aiConfigured?'AI terhubung':'AI belum dikonfigurasi'}}</span></header>
 <div class="content"><div v-if="error" class="error banner" role="alert">{{error}}<button class="icon-button" @click="error=''">×</button></div>
 <template v-if="view==='dashboard'">
 <div class="page-heading"><div><span class="eyebrow">YOUR AUCTION WORKSPACE</span><h1>Temukan ruang untung.</h1><p>Mulai dari katalog. Akhiri dengan batas bid yang jelas.</p></div><button class="primary" @click="view='catalogs'"><UploadCloud :size="18"/> Upload katalog</button></div>
 <div class="stats"><article><span>Katalog tersimpan</span><strong>{{catalogs.length.toString().padStart(2,'0')}}</strong><small>Seluruh sesi lelang</small></article><article><span>Unit dianalisis</span><strong>{{results.length.toString().padStart(2,'0')}}</strong><small>{{selected?.name||'Belum ada analisis aktif'}}</small></article><article><span>Layak bid</span><strong class="green">{{bids.toString().padStart(2,'0')}}</strong><small>Memenuhi filter & perhitungan</small></article><article><span>Profit kandidat teratas</span><strong>{{short(top?.profit)}}</strong><small>Estimasi pada harga dasar</small></article></div>
 <div class="overview-grid"><section class="hero-panel"><span class="eyebrow">A CLEARER WAY TO BID</span><h2>Harga murah belum<br>tentu <em>deal yang bagus.</em></h2><p>Hitung biaya, tandai risiko, dan pilih unit yang masuk dengan strategi kamu.</p><button @click="view='catalogs'">Mulai analisis <ArrowUpRight :size="20"/></button><div class="hero-numbers"><div><small>01</small><b>Upload PDF</b></div><div><small>02</small><b>Atur strategi</b></div><div><small>03</small><b>Tentukan max bid</b></div></div></section><section class="panel formula"><span class="eyebrow">THE BID DISCIPLINE</span><h3>Batas bid, bukan feeling.</h3><p>Harga jual konservatif</p><p>− Target profit</p><p>− Servis, pajak & cadangan</p><p>− Biaya lelang</p><div class="formula-result">= Max bid aman <Check :size="20"/></div><small>Batas ini juga dibatasi modal tersedia dan biaya lelang persentase.</small></section></div>
 <section class="panel"><div class="section-head"><h3>Katalog terbaru</h3><button class="text-button" @click="view='catalogs'">Lihat semua <ArrowUpRight :size="16"/></button></div><div v-if="!catalogs.length" class="empty"><Files :size="32"/><h3>Garasi analisis masih kosong</h3><p>Upload katalog PDF untuk mulai menyeleksi unit lelang.</p></div><button v-for="c in catalogs.slice(0,4)" :key="c.id" class="catalog-row" @click="loadCatalog(c)"><span class="file-icon"><FileText :size="22"/></span><span><b>{{c.name}}</b><small>{{c.house}} · {{c.total_lots}} unit</small></span><span class="badge" :class="c.status">{{statusLabel(c.status)}}</span><ChevronRight :size="18"/></button></section>
 </template>
 <template v-if="view==='catalogs'">
 <div class="page-heading"><div><span class="eyebrow">START WITH THE SOURCE</span><h1>Katalog lelang</h1><p>PDF tersimpan. Hasil ekstraksi bisa dikoreksi dan dianalisis ulang.</p></div><button class="secondary" @click="perform(refreshCatalogs)"><RefreshCw :size="16"/> Refresh</button></div>
 <div v-if="!activeHouses.length" class="info-note">Tambahkan atau aktifkan balai lelang melalui menu Balai lelang sebelum upload PDF.</div><div v-else class="info-note">Tarif balai terpilih: {{idr(activeHouses.find(h=>h.id===house)?.admin_fee)}} admin + {{activeHouses.find(h=>h.id===house)?.tax_percent}}% dari bid. Tarif disimpan bersama katalog.</div><section class="panel upload-panel"><div class="upload-symbol"><UploadCloud :size="35"/></div><div><h3>Bawa katalog berikutnya ke garasi.</h3><p>PDF teks atau scan · maksimal 20 MB / 150 halaman</p><p class="muted">Ekstraksi memanggil OpenAI API dan memakai kuota API server kamu.</p></div><form @submit.prevent="upload"><select v-model="house" required><option value="" disabled>Pilih balai lelang</option><option v-for="h in activeHouses" :key="h.id" :value="h.id">{{h.name}}</option></select><input ref="uploadInput" type="file" accept="application/pdf,.pdf" @change="file=$event.target.files[0]" required><button class="primary" :disabled="busy||!config.aiConfigured||!house">{{busy?'Mengunggah…':'Upload & ekstrak'}}<ArrowUpRight :size="17"/></button></form></section>
 <section class="panel"><div class="section-head"><h3>Semua katalog <span class="count">{{catalogs.length}}</span></h3></div><div v-if="!catalogs.length" class="empty"><Files :size="30"/><p>Belum ada katalog. Pilih file PDF di atas.</p></div><button v-for="c in catalogs" :key="c.id" class="catalog-row" @click="loadCatalog(c)"><span class="file-icon"><FileText :size="22"/></span><span><b>{{c.name}}</b><small>{{c.house}} · {{c.total_lots}} unit · {{new Date(c.created_at).toLocaleDateString('id-ID')}}<em v-if="c.error">{{c.error}}</em></small></span><span class="badge" :class="c.status">{{statusLabel(c.status)}} <template v-if="c.status==='EXTRACTING'">{{c.progress}}%</template></span><ChevronRight :size="18"/></button></section>
 </template>
 <template v-if="['analysis','watchlist'].includes(view)">
 <div class="page-heading"><div><span class="eyebrow">{{view==='watchlist'?'YOUR BIDDING SHORTLIST':'FROM CATALOG TO DECISION'}}</span><h1>{{view==='watchlist'?'Bid board':'Analisis unit'}}</h1><p>{{selected?`${selected.house} · ${selected.name}`:'Pilih katalog untuk membuka workspace analisis.'}}</p></div><div class="heading-actions"><button v-if="selected" class="secondary" @click="openPdf"><FileText :size="16"/> PDF sumber</button><button v-if="analysis?.status==='READY'" class="secondary" @click="download">Export JSON</button></div></div>
 <div v-if="!selected" class="panel empty"><Car :size="38"/><h3>Belum ada katalog dipilih</h3><p>Buka katalog lelang untuk melihat unit dan analisisnya.</p><button class="primary" @click="view='catalogs'">Pilih katalog</button></div>
 <template v-else>
 <section class="panel house-selection"><div><h3>Balai & tarif katalog</h3><p v-if="selected.fee_snapshot">{{selected.house}} · {{idr(selected.fee_snapshot.adminFee)}} admin + {{selected.fee_snapshot.taxPercent}}% dari bid. ALL IN lelang = bid + admin + pajak lelang.</p><p v-else>Tarif belum tersedia. Pilih balai untuk menghitung ALL IN dan menjalankan analisis.</p><small>Perubahan master tidak mengubah tarif katalog ini. Terapkan tarif untuk memperbarui katalog; hasil analisis lama tetap tersimpan.</small></div><div class="heading-actions"><select v-model="catalogHouse"><option value="" disabled>Pilih balai</option><option v-for="h in activeHouses" :key="h.id" :value="h.id">{{h.name}}</option></select><button class="secondary" :disabled="busy||!catalogHouse" @click="applyCatalogHouse">Terapkan tarif</button></div></section>
 <div v-if="selected.status!=='READY'" class="panel process-state"><RefreshCw :size="25"/><h3>{{statusLabel(selected.status)}}</h3><p>{{selected.error||`Ekstraksi katalog ${selected.progress}%. Status diperbarui otomatis.`}}</p><button v-if="selected.status==='FAILED'" class="primary" :disabled="busy" @click="retryExtraction"><RefreshCw :size="16"/> Coba ulang ekstraksi</button></div>
 <template v-else>
 <section v-if="view==='analysis'" class="panel strategy-panel"><div class="section-head"><div><span class="eyebrow">YOUR RULES, YOUR CAPITAL</span><h3>Parameter analisis</h3></div><span class="tag">IDR</span></div><form @submit.prevent="run"><div class="field-grid"><label v-for="[key,label] in moneyFields" :key="key">{{label}}<input v-model.number="criteria[key]" type="number" :min="['capital','maxPerUnit','maxBid'].includes(key)?1:0" max="100000000000" step="100000" required></label><label>Tahun minimal<input v-model.number="criteria.minYear" type="number" min="1950" max="2100" required></label><label>KM maksimal<input v-model.number="criteria.maxKilometer" type="number" min="1" required></label><label>Transmisi<select v-model="criteria.transmission"><option value="ALL">Semua</option><option value="MT">Manual</option><option value="AT">Automatic / CVT</option></select></label><label>Target pembeli<select v-model="criteria.buyer"><option value="DEALER">Pedagang</option><option value="RETAIL">Retail</option></select></label><label>Strategi<select v-model="criteria.strategy"><option value="FAST">Perputaran cepat</option><option value="BALANCED">Seimbang</option><option value="MARGIN">Prioritas margin</option></select></label></div><div class="checks"><label><Check :size="16"/> STNK ADA wajib — unit lain tidak dikirim ke AI</label><label><input v-model="criteria.requireBpkb" type="checkbox"> Wajib BPKB ada</label></div><div class="info-note"><button type="button" class="text-button" :disabled="busy||!selected.fee_snapshot" @click="previewBid">Hitung ALL IN batas bid</button><p v-if="bidPreview?.available">Pada bid {{idr(bidPreview.bid)}}: admin {{idr(bidPreview.adminFee)}} + pajak {{idr(bidPreview.auctionTax)}} = ALL IN lelang {{idr(bidPreview.auctionAllIn)}}. Belum termasuk servis/pajak kendaraan/transport. Klik hitung lagi setelah mengubah bid atau tarif.</p></div><label>Instruksi tambahan<textarea v-model="criteria.instructions" maxlength="3000" rows="2" placeholder="Contoh: Fokus mobil yang mudah dijual ke pedagang Jakarta/Bekasi. Tandai risiko transmisi dan surat-surat."/></label><div class="form-footer"><p><Sparkles :size="16"/> Data tersimpan dipakai kembali. Analisis ulang menggunakan kuota API.</p><button class="primary" :disabled="busy||!selected.fee_snapshot||['QUEUED','PROCESSING'].includes(analysis?.status)"><Sparkles :size="17"/>{{analysis?'Analisis ulang':'Analisis katalog'}}</button></div></form></section>
 <section v-if="view==='analysis'" class="panel"><div class="section-head"><div><h3>Periksa hasil ekstraksi <span class="count">{{lots.length}}</span></h3><p>Verifikasi lot dan isi pembanding harga agar unit dapat berstatus BID.</p></div></div><div class="table-wrap"><table><thead><tr><th>LOT</th><th>UNIT</th><th>HARGA DASAR</th><th>ALL IN LELANG</th><th>STNK</th><th>SUMBER</th><th>VERIFIKASI</th><th/></tr></thead><tbody><tr v-for="l in lots" :key="l.id"><td class="lot-no">{{l.lot_number}}</td><td><b>{{l.data.vehicle}}</b><small>{{l.data.year||'Tahun ?'}} · {{l.data.transmission||'Transmisi ?'}} · {{l.data.kilometer?.toLocaleString('id-ID')||'?'}} km</small></td><td>{{idr(l.data.basePrice)}}</td><td><b>{{idr(l.auctionCost?.auctionAllIn)}}</b><small v-if="l.auctionCost?.available">Admin {{short(l.auctionCost.adminFee)}} + pajak {{short(l.auctionCost.auctionTax)}}</small></td><td><span class="badge" :class="l.data.stnk==='ADA'?'BID':'SKIP'">{{l.data.stnk||'UNKNOWN'}}</span></td><td>Hal. {{l.data.sourcePage||'?'}}</td><td><span class="badge" :class="l.verified?'BID':'REVIEW'">{{l.verified?'Terverifikasi':'Periksa'}}</span></td><td><button class="text-button" @click="openEdit(l)">Edit <ChevronRight :size="14"/></button><button class="text-button" :disabled="!selected.fee_snapshot" @click="newWon(l)">Catat menang</button></td></tr></tbody></table></div></section>
 <section v-if="analysis" class="panel"><div class="section-head"><div><span class="eyebrow">THE DEAL SHORTLIST</span><h3>{{view==='watchlist'?'Unit pilihan kamu':'Ranking & rekomendasi'}}</h3><p>Profit memakai harga dasar; max bid dibatasi parameter user. AI menilai {{analysis.usage?.aiAnalyzedLots??'—'}} unit, {{analysis.usage?.filteredLots??'—'}} unit disaring backend.</p></div><select v-if="history.length" :value="analysis.id" @change="perform(async()=>{analysis=await api('/analyses/'+$event.target.value);criteria={...criteria,...analysis.parameters,maxBid:analysis.parameters.maxBid||60000000,requireStnk:true}})"><option v-for="h in history" :key="h.id" :value="h.id">{{new Date(h.created_at).toLocaleString('id-ID')}} · {{statusLabel(h.status)}}</option></select></div><div v-if="analysis.status!=='READY'" class="process-state"><RefreshCw :size="25"/><h3>{{statusLabel(analysis.status)}}</h3><p>{{analysis.error||'AI sedang menilai unit. Hasil akan muncul otomatis.'}}</p></div><template v-else><div class="table-tools"><label class="search"><Search :size="16"/><input v-model="query" placeholder="Cari model atau nomor lot…"></label><div class="filter-tabs"><button v-for="[id,label] in [['ALL','Semua'],['BID','Layak bid'],['REVIEW','Periksa'],['SKIP','Lewati']]" :key="id" :class="{active:filter===id}" @click="filter=id">{{label}}</button></div></div><div class="table-wrap"><table><thead><tr><th>LOT / UNIT</th><th>STATUS</th><th>SKOR</th><th>HARGA DASAR</th><th>MAX BID</th><th>JUAL KONSERVATIF</th><th>LABA</th><th/></tr></thead><tbody><tr v-for="r in visible" :key="r.lotId" @click="detail=r" class="clickable"><td><small>LOT {{r.lotNumber}}</small><b>{{r.vehicle}}</b></td><td><span class="badge" :class="r.recommendation">{{statusLabel(r.recommendation)}}</span></td><td><span class="score" :class="{green:r.score>=75}">{{r.score}}<small>/100</small></span></td><td>{{short(r.basePrice)}}</td><td class="strong">{{short(r.maxBid)}}</td><td>{{short(r.sellPrice)}}</td><td :class="r.profit>0?'green':'red'">{{short(r.profit)}}</td><td><button class="icon-button" :class="{saved:r.watchlisted}" :aria-label="r.watchlisted?'Hapus dari bid board':'Simpan ke bid board'" @click.stop="setWatch(r)"><Bookmark :size="18"/></button></td></tr></tbody></table><div v-if="!visible.length" class="empty"><Bookmark :size="28"/><p>{{view==='watchlist'?'Simpan unit dari ranking untuk membangun bid board.':'Tidak ada unit sesuai filter.'}}</p></div></div><div class="table-foot"><AlertTriangle :size="15"/> Max bid belum tersedia tanpa pembanding. Estimasi AI tidak dipakai sebagai harga pasar terverifikasi.</div></template></section>
 </template></template>
 </template>
<template v-if="view==='won'">
 <div class="page-heading"><div><span class="eyebrow">FROM WINNING TO SELLING</span><h1>Unit dimenangkan</h1><p>Catat modal aktual, pengeluaran, dan hasil penjualan setiap unit.</p></div><button class="primary" @click="newWon()">+ Tambah unit</button></div>
 <div class="stats"><article><span>Dana sesuai rumus sheet</span><strong>{{short(funds.funds)}}</strong><small>Dana awal + akumulasi margin real</small></article><article><span>Laba / rugi terealisasi</span><strong>{{short(funds.realizedProfit)}}</strong><small>Hanya unit yang sudah terjual</small></article><article><span>Modal unit belum terjual</span><strong>{{short(funds.unsoldCapital)}}</strong><small>ALL IN termasuk pengeluaran</small></article><article><span>Unit dimenangkan</span><strong>{{wonUnits.length}}</strong><small>{{wonUnits.filter(u=>u.summary.status==='SOLD').length}} unit terjual</small></article></div>
 <section class="panel"><form class="heading-actions" @submit.prevent="saveFunds"><label>Dana awal (Rp)<input v-model.number="startingFunds" type="number" min="0" max="100000000000" required></label><button class="secondary" :disabled="busy">Simpan dana awal</button></form><p>Dana ini mengikuti rumus spreadsheet, bukan saldo kas bank. Modal unit belum terjual ditampilkan terpisah.</p></section>
 <section class="panel"><div class="table-wrap"><table><thead><tr><th>UNIT / BALAI</th><th>MENANG AKTUAL</th><th>MODAL REAL</th><th>PENGELUARAN</th><th>ALL IN AKHIR</th><th>TARGET JUAL</th><th>MARGIN HARAPAN</th><th>DEAL JUAL</th><th>MARGIN REAL</th><th>STATUS</th><th/></tr></thead><tbody><tr v-for="u in wonUnits" :key="u.id"><td><b>{{u.data.vehicle}}</b><small>{{u.data.plate||'—'}} · {{u.fee_snapshot.name}} · LOT {{u.data.lotNumber||'—'}}</small></td><td>{{idr(u.data.winningBid)}}</td><td>{{idr(u.summary.auctionAllIn)}}</td><td>{{idr(u.summary.expenseTotal)}}</td><td><b>{{idr(u.summary.totalCost)}}</b></td><td>{{idr(u.data.targetPrice)}}</td><td>{{idr(u.summary.expectedMargin)}}</td><td>{{idr(u.data.dealPrice)}}</td><td :class="u.summary.realMargin<0?'red':'green'">{{idr(u.summary.realMargin)}}</td><td>{{u.summary.status==='SOLD'?'Terjual':'Belum terjual'}}</td><td><button class="text-button" @click="perform(()=>loadWon(u.id))">Rincian</button><button class="text-button" @click="editWon(u)">Edit unit</button></td></tr></tbody></table><div v-if="!wonUnits.length" class="empty"><Car :size="30"/><p>Tambahkan unit manual atau pilih Catat menang pada lot katalog.</p></div></div></section>
 </template>
 <template v-if="view==='houses'"><div class="page-heading"><div><span class="eyebrow">AUCTION FEE SETTINGS</span><h1>Balai lelang</h1><p>Atur admin dalam rupiah dan pajak lelang sebagai persentase dari harga bid.</p></div><button class="primary" @click="editHouse(null)">+ Tambah balai</button></div><section v-if="houseForm" class="panel"><h3>{{houseForm.id?'Edit':'Tambah'}} balai lelang</h3><form @submit.prevent="saveHouse"><div class="field-grid"><label>Nama balai<input v-model="houseForm.name" required maxlength="120"></label><label>Admin lelang (Rp)<input v-model.number="houseForm.adminFee" type="number" min="0" max="100000000000" required></label><label>Pajak dari bid (%)<input v-model.number="houseForm.taxPercent" type="number" min="0" max="100" step="0.0001" required></label></div><div class="checks"><label><input v-model="houseForm.active" type="checkbox"> Aktif untuk katalog baru</label></div><div class="heading-actions"><button class="primary" :disabled="busy">Simpan balai</button><button class="secondary" type="button" @click="houseForm=null">Batal</button></div></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>BALAI</th><th>ADMIN</th><th>PAJAK DARI BID</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody><tr v-for="h in houses" :key="h.id"><td><b>{{h.name}}</b></td><td>{{idr(h.admin_fee)}}</td><td>{{h.tax_percent}}%</td><td><span class="badge" :class="h.active?'BID':'SKIP'">{{h.active?'Aktif':'Nonaktif'}}</span></td><td><button class="text-button" @click="editHouse(h)">Edit balai</button> <button class="text-button" @click="deleteHouse(h)">Hapus</button></td></tr></tbody></table></div><p>JBA awal: admin Rp3 juta + pajak 1,1% dari bid, sesuai parameter yang kamu berikan. Tarif balai lain diisi manual.</p></section></template>
 <template v-if="view==='ai'"><div class="page-heading"><div><span class="eyebrow">TRANSPARENT INTELLIGENCE</span><h1>AI & penggunaan</h1><p>Lihat konfigurasi, penggunaan token, dan batas analisis.</p></div></div><div class="stats"><article><span>Model aktif</span><strong class="model-name">{{config.model}}</strong><small>{{config.aiConfigured?'API key dikonfigurasi':'API key belum tersedia'}}</small></article><article><span>Input token</span><strong>{{(analysis?.usage?.inputTokens||0).toLocaleString('id-ID')}}</strong><small>Analisis terpilih</small></article><article><span>Output token</span><strong>{{(analysis?.usage?.outputTokens||0).toLocaleString('id-ID')}}</strong><small>Analisis terpilih</small></article><article><span>Estimasi biaya analisis</span><strong>${{usageCost.toFixed(4)}}</strong><small>Berdasarkan tarif yang kamu isi</small></article></div><section class="panel"><h3>Tarif model (USD / 1 juta token)</h3><p>Isi tarif dari dashboard provider. Estimasi ini tidak termasuk ekstraksi PDF, cached token, maupun panggilan gagal.</p><div class="field-grid rates"><label>Input<input v-model.number="inputRate" type="number" min="0" step="0.01"></label><label>Output<input v-model.number="outputRate" type="number" min="0" step="0.01"></label></div></section><section class="panel ai-explanation"><h3>Bagaimana rekomendasi dibuat</h3><div><b>01 · Ekstrak fakta</b><p>PDF dibagi per 3 halaman. AI membaca spesifikasi dan mencatat sumber; field yang tidak terbaca dibiarkan kosong.</p></div><div><b>02 · Nilai risiko</b><p>AI memberikan indikasi kondisi, demand, estimasi servis, dan alasan sesuai parameter. Demand dan waktu jual belum memakai histori transaksi lokal.</p></div><div><b>03 · Hitung di Java</b><p>Harga jual memakai pembanding terendah × 95% untuk retail / 85% untuk pedagang. Ini asumsi konservatif yang harus kamu tinjau. Biaya, target profit, dan batas modal menghasilkan max bid.</p></div><div><b>04 · Verifikasi sebelum bid</b><p>Status BID memerlukan data terverifikasi, pembanding harga, dan filter yang terpenuhi. Unit tanpa STNK ADA, di atas batas bid, atau jelas melanggar parameter tidak dikirim ke AI. Tidak ada scraping harga otomatis pada MVP ini.</p></div></section></template>
 <footer>PHIVEGARAGE <span>Know the cost. Respect the limit.</span><small>MVP · 0.1</small></footer>
 </div></main>
 <div v-if="wonDetail&&!wonForm" class="modal-backdrop" @click.self="wonDetail=null"><section class="modal wide"><button class="modal-close icon-button" @click="wonDetail=null"><X/></button><span class="eyebrow">ACTUAL UNIT COSTS</span><h2>{{wonDetail.data.vehicle}}</h2><p>{{wonDetail.fee_snapshot.name}} · Tarif tersimpan: admin {{idr(wonDetail.summary.adminFee)}} + {{wonDetail.fee_snapshot.taxPercent}}% dari bid</p><div v-if="error" class="error">{{error}}</div><dl class="won-costs"><template v-for="[key,label] in [['idealAcquisition','Modal maksimal / menang ideal'],['auctionTax','Pajak lelang aktual'],['auctionAllIn','Modal real / ALL IN lelang'],['expenseTotal','Perbaikan + penggunaan'],['totalCost','Harga akhir ALL IN'],['expectedMargin','Margin harapan'],['realMargin','Margin real']]" :key="key"><dt>{{label}}</dt><dd>{{idr(wonDetail.summary[key])}}</dd></template></dl><p>Median pasar {{idr(wonDetail.data.medianPrice)}} · Menang {{wonDetail.data.wonDate}} · Terjual {{wonDetail.data.soldDate||'—'}}</p><p>{{wonDetail.data.notes}}</p><p v-if="wonDetail.data.link">Referensi: {{wonDetail.data.link}}</p><div class="section-head"><h3>Pengeluaran unit</h3><button class="secondary" @click="editExpense()">+ Tambah pengeluaran</button></div><div class="table-wrap"><table><thead><tr><th>TANGGAL</th><th>KATEGORI / CATATAN</th><th>NOMINAL</th><th/></tr></thead><tbody><tr v-for="e in wonDetail.expenses" :key="e.id"><td>{{e.expense_date}}</td><td><b>{{e.category}}</b><small>{{e.description}}</small></td><td>{{idr(e.amount)}}</td><td><button class="text-button" @click="editExpense(e)">Edit biaya</button><button class="text-button" @click="deleteExpense(e)">Hapus biaya</button></td></tr></tbody></table></div><form v-if="expenseForm" @submit.prevent="saveExpense"><h3>{{expenseForm.id?'Edit':'Tambah'}} pengeluaran</h3><div class="field-grid"><label>Tanggal biaya<input v-model="expenseForm.date" type="date" required></label><label>Kategori<input v-model="expenseForm.category" list="expense-categories" required maxlength="60"><datalist id="expense-categories"><option v-for="c in ['Servis','BBM','Pajak / dokumen','Tol','Cuci','Iklan','Lainnya']" :key="c">{{c}}</option></datalist></label><label>Nominal biaya (Rp)<input v-model.number="expenseForm.amount" type="number" min="1" max="100000000000" required></label></div><label>Catatan biaya<input v-model="expenseForm.description" required maxlength="1000"></label><div class="heading-actions"><button class="primary" :disabled="busy">Simpan pengeluaran</button><button type="button" class="secondary" @click="expenseForm=null">Batal</button></div></form><div class="heading-actions"><button class="secondary" @click="editWon(wonDetail)">Edit unit / catat penjualan</button><button class="text-button" :disabled="busy" @click="deleteWon(wonDetail)">Hapus unit</button></div></section></div>
 <div v-if="wonForm" class="modal-backdrop" @click.self="wonForm=null"><form class="modal wide" @submit.prevent="saveWon"><button type="button" class="modal-close icon-button" @click="wonForm=null"><X/></button><h2>{{wonForm.id?'Edit':'Catat'}} unit dimenangkan</h2><div v-if="error" class="error">{{error}}</div><label>Balai lelang<select v-model="wonForm.houseId" :disabled="!!wonForm.id||!!wonForm.sourceLotId" required><option value="" disabled>Pilih balai</option><option v-for="h in houses.filter(h=>h.active||h.id===wonForm.houseId)" :key="h.id" :value="h.id">{{h.name}}</option></select></label><p>Tarif disimpan saat pencatatan; unit dari katalog memakai tarif katalog. Balai dan sumber terkunci setelah disimpan.</p><div class="field-grid"><label v-for="[key,label,type,required] in wonFields" :key="key">{{label}}<input v-model="wonForm.data[key]" :type="type" :required="required" :min="type==='number'?(key==='year'?1950:['kilometer','basePrice'].includes(key)?0:1):undefined" :max="type==='number'?(key==='year'?2100:100000000000):undefined" :maxlength="key==='vehicle'?300:undefined"></label></div><p>Isi harga deal dan tanggal terjual bersama. Tanpa penjualan, margin real belum dihitung.</p><label>Notes<textarea v-model="wonForm.data.notes" maxlength="5000" rows="3"/></label><button class="primary" :disabled="busy">Simpan unit</button></form></div>
 <div v-if="detail" class="modal-backdrop" @click.self="detail=null"><section class="modal"><button class="modal-close icon-button" @click="detail=null"><X/></button><span class="eyebrow">LOT {{detail.lotNumber}} · UNIT ANALYSIS</span><h2>{{detail.vehicle}}</h2><span class="badge" :class="detail.recommendation">{{statusLabel(detail.recommendation)}} · {{detail.score}}/100</span><div class="detail-stats"><div><small>MAX BID</small><strong>{{idr(detail.maxBid)}}</strong></div><div><small>TOTAL MODAL (HARGA DASAR)</small><strong>{{idr(detail.totalCost)}}</strong></div><div><small>HARGA JUAL KONSERVATIF</small><strong>{{idr(detail.sellPrice)}}</strong></div><div><small>ESTIMASI PROFIT</small><strong>{{idr(detail.profit)}}</strong></div></div><section v-if="detail.costs" class="cost-panel"><h3>Rincian biaya unit</h3><dl><template v-for="[key,label] in [['repair','Servis (buffer / input / AI tertinggi)'],['tax','Pajak & balik nama'],['globalOther','Transport & biaya global'],['lotOther','Biaya tambahan lot'],['riskBuffer','Cadangan risiko'],['auctionFeeAtBase','Admin + pajak lelang pada harga dasar'],['auctionAllInAtBase','ALL IN lelang pada harga dasar'],['auctionAllInAtMaxBid','ALL IN lelang pada max bid']]" :key="key"><dt>{{label}}</dt><dd>{{idr(detail.costs[key])}}</dd></template><dt>Total pada max bid</dt><dd>{{idr(detail.costs.totalAtMaxBid)}}</dd><dt>Profit pada max bid</dt><dd>{{idr(detail.costs.profitAtMaxBid)}}</dd></dl><p>Biaya lelang: {{idr(detail.costs.auctionFixedFee)}} tetap + {{detail.costs.auctionFeePercent}}% bid. Nilai di atas memakai parameter saat analisis dibuat.</p><p v-if="detail.maxBid===0">Tidak ada bid positif yang memenuhi modal dan target profit.</p></section><div v-if="detail.blockers.length" class="review-box"><h3>Yang perlu diselesaikan</h3><ul><li v-for="b in detail.blockers" :key="b">{{b}}</li></ul></div><template v-if="detail.ai"><h3>Alasan AI</h3><ul><li v-for="r in detail.ai.reasons" :key="r">{{r}}</li></ul><h3>Risiko & inspeksi</h3><ul><li v-for="r in detail.ai.risks" :key="r">{{r}}</li></ul><div class="info-note">Harga indikatif AI: {{idr(detail.ai.indicativeSellPrice)}} · Waktu jual indikatif: {{detail.ai.daysMin??'?'}}–{{detail.ai.daysMax??'?'}} hari. Keduanya belum terverifikasi.</div></template><div v-else class="info-note">Unit ini disaring oleh backend dan tidak dikirim ke AI. Lihat alasan pada daftar di atas.</div><button class="primary" @click="setWatch(detail)"><Bookmark :size="17"/>{{detail.watchlisted?'Hapus dari bid board':'Simpan ke bid board'}}</button></section></div>
 <div v-if="edit" class="modal-backdrop" @click.self="edit=null"><form class="modal wide" @submit.prevent="saveLot"><button type="button" class="modal-close icon-button" @click="edit=null"><X/></button><span class="eyebrow">VERIFY THE FACTS</span><h2>Periksa lot {{edit.lot_number}}</h2><div v-if="error" class="error">{{error}}</div><div class="source-quote">Halaman {{edit.data.sourcePage||'?'}} · {{edit.data.sourceQuote||'Kutipan sumber tidak tersedia'}}</div><div class="field-grid"><label>Nomor lot<input v-model="edit.data.lotNumber" required></label><label>Nama unit<input v-model="edit.data.vehicle" required></label><label>Tahun<input v-model.number="edit.data.year" type="number" min="1950" max="2100"></label><label>Transmisi<select v-model="edit.data.transmission"><option value="UNKNOWN">Belum diketahui</option><option value="MT">MT</option><option value="AT">AT / CVT</option></select></label><label>Kilometer<input v-model.number="edit.data.kilometer" type="number" min="0"></label><label>Harga dasar<input v-model.number="edit.data.basePrice" type="number" min="0"></label><label>STNK<select v-model="edit.data.stnk"><option value="UNKNOWN">Belum diketahui</option><option value="ADA">Ada</option><option value="TIDAK_ADA">Tidak ada</option></select></label><label>BPKB<select v-model="edit.data.bpkb"><option value="UNKNOWN">Belum diketahui</option><option value="ADA">Ada</option><option value="TIDAK_ADA">Tidak ada</option></select></label><label>Jatuh tempo pajak<input v-model="edit.data.taxExpiry" type="date"></label><label>Estimasi servis aktual<input v-model.number="edit.data.repairCost" type="number" min="0" placeholder="Kosong = buffer"></label><label>Pajak / balik nama aktual<input v-model.number="edit.data.taxCost" type="number" min="0" placeholder="Kosong = buffer"></label><label>Biaya tambahan unit<input v-model.number="edit.data.otherCost" type="number" min="0"></label></div><label>Catatan kondisi & dokumen<textarea v-model="edit.data.notes" rows="3"/></label><h3>Pembanding harga</h3><p class="muted">Gunakan unit dengan tipe, tahun, kondisi, dan lokasi yang sebanding. Harga listing adalah harga penawaran.</p><div v-for="(c,i) in edit.data.comparables" :key="i" class="comparable"><input v-model="c.url" type="url" placeholder="https://…" required><input v-model.number="c.price" type="number" min="1" placeholder="Harga IDR" required><input v-model="c.observedDate" type="date" required><button type="button" class="icon-button" @click="edit.data.comparables.splice(i,1)"><X :size="16"/></button></div><button type="button" class="secondary" @click="edit.data.comparables.push({url:'',price:null,observedDate:new Date().toLocaleDateString('en-CA'),notes:''})">+ Tambah pembanding</button><div class="checks"><label><input v-model="edit.verified" type="checkbox"> Saya sudah memeriksa data lot terhadap sumber.</label></div><div class="info-note">Perubahan ini berlaku pada analisis berikutnya. Jalankan analisis ulang untuk memperbarui ranking.</div><button class="primary" :disabled="busy">Simpan lot <Check :size="17"/></button></form></div>
 </div>
</template>
